// Additive score: insult -1, apology +1, gift +0.6; warm iff score > 0.5.
function visible(actions) {
  let score = 0;
  for (const action of actions) {
    if (action === "insult") {
      score -= 1;
    } else if (action === "apologise") {
      score += 1;
    } else if (action === "gift") {
      score += 0.6;
    }
  }
  return { mood: score > 0.5 ? "warm" : "cold" };
}

// Two reservoirs: insults build anger; apology lowers anger or builds affection if calm; gift builds affection only if calm; warm iff calm and affectionate.
function visible(actions) {
  let anger = 0;
  let affection = 0;
  for (const action of actions) {
    if (action === "insult") {
      anger += 2;
    } else if (action === "apologise") {
      if (anger > 0) {
        anger = Math.max(0, anger - 2);
      } else {
        affection += 1;
      }
    } else if (action === "gift") {
      if (anger === 0) {
        affection += 1;
      }
    }
  }
  return { mood: anger === 0 && affection > 0 ? "warm" : "cold" };
}

// One grudge per unapologised insult; apology cancels one grudge if any; gift is ignored; warm iff no grudge.
function visible(actions) {
  let grudge = 0;
  for (const action of actions) {
    if (action === "insult") {
      grudge += 1;
    } else if (action === "apologise") {
      if (grudge > 0) {
        grudge -= 1;
      }
    }
  }
  return { mood: grudge === 0 ? "warm" : "cold" };
}

// Score: insult -1, apology +1, gift +1 only immediately after an apology; warm iff score > 0.
function visible(actions) {
  let score = 0;
  let previous = null;
  for (const action of actions) {
    if (action === "insult") {
      score -= 1;
    } else if (action === "apologise") {
      score += 1;
    } else if (action === "gift") {
      if (previous === "apologise") {
        score += 1;
      }
    }
    previous = action;
  }
  return { mood: score > 0 ? "warm" : "cold" };
}

